package dev.zyon;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
public class ChatAndHealthTest {
 @Rule public TemporaryFolder folder=new TemporaryFolder();
 @Test public void allArmorSlotsAreDistinctAndCorrect(){assertEquals(3,Widgets.armorSlot("helmet"));assertEquals(2,Widgets.armorSlot("chestplate"));assertEquals(1,Widgets.armorSlot("leggings"));assertEquals(0,Widgets.armorSlot("boots"));}
 @Test public void healthIsNoLongerDraggableAndOldPositionDoesNotReturn()throws Exception{Zyon c=new Zyon();Catalog.register(c.features);Feature health=c.feature("health");assertFalse(Catalog.widget(health));assertTrue(Catalog.widget(c.feature("helmet")));assertTrue(Catalog.widget(c.feature("leggings")));File dir=folder.newFolder();Files.write(new File(dir,"old.json").toPath(),"{\"schema\":1,\"modules\":{\"health\":{\"enabled\":true,\"settings\":{\"x\":91,\"y\":12,\"scale\":1.2,\"text\":12345}}}}".getBytes(StandardCharsets.UTF_8));new Profiles(c,dir).load("old");assertTrue(health.enabled());assertEquals(1.2,health.number("scale"),.001);assertEquals(12345,health.number("text"),0);for(Setting setting:health.settings)assertFalse(setting.id.equals("x")||setting.id.equals("y")||setting.id.startsWith("align"));}
 @Test public void labelsRespectVisibilityAndDistance(){assertTrue(HealthPolicy.visible(true,false,0,false,false,false,false,false,20,true));assertTrue(HealthPolicy.visible(true,true,2,false,false,false,false,false,0,true));assertFalse(HealthPolicy.visible(true,true,0,false,false,false,false,false,0,true));assertFalse(HealthPolicy.visible(false,false,0,false,false,false,false,false,1,true));assertFalse(HealthPolicy.visible(true,false,0,true,false,false,false,false,1,true));assertFalse(HealthPolicy.visible(true,false,0,false,true,false,false,false,1,true));assertFalse(HealthPolicy.visible(true,false,0,false,false,true,false,false,1,true));assertFalse(HealthPolicy.visible(true,false,0,false,false,false,true,false,1,true));assertFalse(HealthPolicy.visible(true,false,0,false,false,false,false,true,1,true));assertFalse(HealthPolicy.visible(true,false,0,false,false,false,false,false,1025,true));assertFalse(HealthPolicy.visible(true,false,0,false,false,false,false,false,1,false));}
 @Test public void healthFormatsServerValuesWithoutInventingExtraHealth(){assertEquals("7.5",HealthPolicy.value(7.5f,20,0,0));assertEquals("50%",HealthPolicy.value(10,20,4,1));assertEquals("10 + 4",HealthPolicy.value(10,20,4,2));assertEquals("?",HealthPolicy.value(Float.NaN,20,0,0));assertEquals("0",HealthPolicy.value(-1,20,0,0));}
 @Test public void healthLabelStaysAboveNameAtEverySupportedScale(){for(double scale:new double[]{.7,1,1.5}){assertTrue(HealthPolicy.height(scale,false)-10*.026666667*scale>.5);assertTrue(HealthPolicy.height(scale,true)-10*.026666667*scale>.8);}}
 @Test public void messagesStayEmptyUntilUserEditsAndSurviveReload()throws Exception{File file=new File(folder.newFolder(),"chat/autotext.json");AutoTextStore store=new AutoTextStore(file);store.load();for(int i=0;i<6;i++)assertEquals("",store.message(i));store.set(0,"Saudacao","Boa noite, pessoal!");store.set(5,"Comando","/spawn");store.save();AutoTextStore reloaded=new AutoTextStore(file);reloaded.load();assertEquals("Saudacao",reloaded.name(0));assertEquals("Boa noite, pessoal!",reloaded.message(0));assertEquals("/spawn",reloaded.message(5));}
 @Test public void chatMessagesCannotExceedVanillaLimitOrContainControlCodes(){char[] many=new char[200];Arrays.fill(many,'a');assertEquals(100,AutoTextStore.clean(new String(many),100).length());assertEquals("abcdef",AutoTextStore.clean("ab\ncd\r\u0000ef\u00a7",100));assertEquals("abc",AutoTextStore.clean("abc\uD83D\uDE00",4));}
 @Test public void corruptMessageFileCannotPartlyReplaceExistingMessages()throws Exception{File file=folder.newFile();AutoTextStore store=new AutoTextStore(file);store.set(0,"Meu","Preservar");Files.write(file.toPath(),"{\"schema\":1,\"slots\":[{\"name\":\"A\",\"message\":\"Nao aplicar\"},null]}".getBytes(StandardCharsets.UTF_8));try{store.load();fail();}catch(IOException expected){assertEquals("Preservar",store.message(0));}assertTrue(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8).contains("Nao aplicar"));}
}
